1	/* statusd's JSON writer (D-045): builds a document in a buffer the caller owns.
2	 *
3	 *     json_t j;  json_init(&j, buf, sizeof buf);
4	 *     json_begin_object(&j);  json_key(&j, "ok");  json_bool(&j, true);  json_end_object(&j);
5	 *     ssize_t n = json_finish(&j);                  -> {"ok":true}
6	 *
7	 * Errors are sticky: a call that runs out of room or is out of order (a value where a key
8	 * belongs, an end that matches no begin, nesting past JSON_MAX_DEPTH) marks the writer
9	 * failed, every later call does nothing, and json_finish returns -1. The caller checks
10	 * once at the end. The writer never writes past cap, and keeps the buffer NUL-terminated.
11	 *
12	 * Strings are ASCII: a byte of 0x80 or more fails the writer, because the control-socket
13	 * text it is made from is ASCII (kv.h) and a byte we cannot vouch for could make invalid
14	 * UTF-8. Integers are written exactly. A JavaScript page reads them as doubles, so a field
15	 * that can pass 2^53 (nanosecond clocks, sequence numbers) must be sent as a string.
16	 * json_double formats with printf, so it depends on the C locale; nothing here calls
17	 * setlocale.
18	 */
19	#ifndef CARWATCH_JSON_H
20	#define CARWATCH_JSON_H
21	
22	#include <stdbool.h>
23	#include <stddef.h>
24	#include <sys/types.h>
25	
26	#define JSON_MAX_DEPTH  8u
27	
28	typedef struct {
29	    char    *buf;
30	    size_t   cap, len;
31	    unsigned depth;                       /* open containers */
32	    bool     is_object[JSON_MAX_DEPTH];   /* per open container: object or array */
33	    bool     has_item[JSON_MAX_DEPTH];    /* per open container: wrote an item already */
34	    bool     after_key;                   /* a key was written; its value must follow */
35	    bool     done;                        /* the one top-level value is complete */
36	    bool     failed;
37	} json_t;
38	
39	void json_init(json_t *j, char *buf, size_t cap);
40	
41	void json_begin_object(json_t *j);
42	void json_end_object(json_t *j);
43	void json_begin_array(json_t *j);
44	void json_end_array(json_t *j);
45	
46	/* Only directly inside an object, and followed by exactly one value. */
47	void json_key(json_t *j, const char *key);
48	
49	void json_string(json_t *j, const char *s);
50	void json_int(json_t *j, long long v);
51	void json_uint(json_t *j, unsigned long long v);
52	void json_double(json_t *j, double v);   /* NaN and infinity fail: a gap is json_null */
53	void json_bool(json_t *j, bool v);
54	void json_null(json_t *j);
55	
56	/* Writes text as a number, exactly as given, if json_is_number accepts it; else fails. */
57	void json_number(json_t *j, const char *text);
58	
59	/* True if text is wholly one number in JSON's grammar: -?(0|[1-9][0-9]*)(\.[0-9]+)?
60	 * ([eE][+-]?[0-9]+)?. Not "+1", "01", ".5", "5.", "1e", "0x10", "NaN" or padded text. */
61	bool json_is_number(const char *text);
62	
63	/* Returns the document's length, in a NUL-terminated buffer, or -1 if the writer failed
64	 * or the document is not exactly one complete value. */
65	ssize_t json_finish(json_t *j);
66	
67	#endif
