/* statusd's JSON writer (D-045): builds a document in a buffer the caller owns.
 *
 *     json_t j;  json_init(&j, buf, sizeof buf);
 *     json_begin_object(&j);  json_key(&j, "ok");  json_bool(&j, true);  json_end_object(&j);
 *     ssize_t n = json_finish(&j);                  -> {"ok":true}
 *
 * Errors are sticky: a call that runs out of room or is out of order (a value where a key
 * belongs, an end that matches no begin, nesting past JSON_MAX_DEPTH) marks the writer
 * failed, every later call does nothing, and json_finish returns -1. The caller checks
 * once at the end. The writer never writes past cap, and keeps the buffer NUL-terminated.
 *
 * Strings are ASCII: a byte of 0x80 or more fails the writer, because the control-socket
 * text it is made from is ASCII (kv.h) and a byte we cannot vouch for could make invalid
 * UTF-8. Integers are written exactly. A JavaScript page reads them as doubles, so a field
 * that can pass 2^53 (nanosecond clocks, sequence numbers) must be sent as a string.
 * json_double formats with printf, so it depends on the C locale; nothing here calls
 * setlocale.
 */
#ifndef CARWATCH_JSON_H
#define CARWATCH_JSON_H

#include <stdbool.h>
#include <stddef.h>
#include <sys/types.h>

#define JSON_MAX_DEPTH  8u

typedef struct {
    char    *buf;
    size_t   cap, len;
    unsigned depth;                       /* open containers */
    bool     is_object[JSON_MAX_DEPTH];   /* per open container: object or array */
    bool     has_item[JSON_MAX_DEPTH];    /* per open container: wrote an item already */
    bool     after_key;                   /* a key was written; its value must follow */
    bool     done;                        /* the one top-level value is complete */
    bool     failed;
} json_t;

void json_init(json_t *j, char *buf, size_t cap);

void json_begin_object(json_t *j);
void json_end_object(json_t *j);
void json_begin_array(json_t *j);
void json_end_array(json_t *j);

/* Only directly inside an object, and followed by exactly one value. */
void json_key(json_t *j, const char *key);

void json_string(json_t *j, const char *s);
void json_int(json_t *j, long long v);
void json_uint(json_t *j, unsigned long long v);
void json_double(json_t *j, double v);   /* NaN and infinity fail: a gap is json_null */
void json_bool(json_t *j, bool v);
void json_null(json_t *j);

/* Writes text as a number, exactly as given, if json_is_number accepts it; else fails. */
void json_number(json_t *j, const char *text);

/* True if text is wholly one number in JSON's grammar: -?(0|[1-9][0-9]*)(\.[0-9]+)?
 * ([eE][+-]?[0-9]+)?. Not "+1", "01", ".5", "5.", "1e", "0x10", "NaN" or padded text. */
bool json_is_number(const char *text);

/* Returns the document's length, in a NUL-terminated buffer, or -1 if the writer failed
 * or the document is not exactly one complete value. */
ssize_t json_finish(json_t *j);

#endif

/* The control socket's reply lines (D-043, D-045): what statusd reads from a source.
 *
 * A reply is zero or more record lines, then one terminator, each line ending in "\n"
 * (a "\r\n" is accepted):
 *
 *     proc name="obdd" up=1 pid=412 src="synth"  a record: a tag, then key=value fields
 *     ok                                         the end of a good reply
 *     err unavailable storaged is down           the end of a refused one: a code, then text
 *
 * Tags, keys and codes are [a-z0-9_]. A value carries its type: in double quotes it is a
 * string (printable ASCII, no '"' and no '\', so nothing is unescaped), bare it is a JSON
 * number (json.h) or null, and anything else bare is refused. So pid="46" and pid=46 are
 * different things, and forgetting the quotes is an error, not a silent change of type.
 * Parsing copies into fixed-size fields: no allocation, and the caller's buffer can go
 * away afterward.
 */
#ifndef CARWATCH_KV_H
#define CARWATCH_KV_H

#include <stddef.h>

#define KV_MAX_LINE     512u   /* bytes in a line, not counting its newline */
#define KV_MAX_FIELDS   16u
#define KV_MAX_TAG      24u    /* these sizes count the NUL */
#define KV_MAX_KEY      24u
#define KV_MAX_VALUE    96u
#define KV_MAX_CODE     24u
#define KV_MAX_REASON   96u

typedef enum {
    KV_RECORD,       /* a tag and its fields */
    KV_OK,           /* the end of a good reply */
    KV_ERR,          /* the end of a refused reply: err_code and err_reason are set */
    KV_BAD,          /* malformed, or over a limit */
    KV_INCOMPLETE    /* no whole line yet, or no terminator yet */
} kv_kind_t;

typedef enum { KV_STR, KV_NUM, KV_NULL } kv_type_t;

typedef struct {
    char      key[KV_MAX_KEY];
    char      val[KV_MAX_VALUE];   /* a string without its quotes; a number or "null" as typed */
    kv_type_t type;
} kv_field_t;

typedef struct {
    char       tag[KV_MAX_TAG];
    kv_field_t f[KV_MAX_FIELDS];
    size_t     nfields;
    char       err_code[KV_MAX_CODE];
    char       err_reason[KV_MAX_REASON];   /* "" if the line gave none */
} kv_line_t;

/* Parses one line, s[0, len), without its newline. s need not be NUL-terminated. *out is
 * cleared first and is meaningful only for KV_RECORD and KV_ERR. */
kv_kind_t kv_parse_line(const char *s, size_t len, kv_line_t *out);

/* Takes the next line from [*cursor, end) and parses it. Advances *cursor past the line's
 * newline, even when the line is KV_BAD, so a caller can skip it. Returns KV_INCOMPLETE,
 * leaving *cursor alone, if no newline remains. */
kv_kind_t kv_reply_next(const char **cursor, const char *end, kv_line_t *out);

/* Walks a whole reply, buf[0, len), and says how it ended: KV_OK, or KV_ERR with *final
 * set (final may be NULL). KV_BAD if any line is bad or anything follows the terminator;
 * KV_INCOMPLETE if the reply stops before its terminator and that terminator's newline. */
kv_kind_t kv_reply_check(const char *buf, size_t len, kv_line_t *final);

/* The value of key on a record line, or NULL if it has none. */
const char *kv_get(const kv_line_t *line, const char *key);

#endif

