1	/* statusd: the phone page and API (D-013, D-043, D-045).
2	 *
3	 * A supervisable daemon (CLAUDE.md section 2.6): it exits 0 on SIGTERM or SIGINT, 1 when it
4	 * cannot run, 2 on bad arguments; it holds no descriptor but its listener (close-on-exec);
5	 * it logs a heartbeat at once and then every --heartbeat-s seconds; and nothing it does
6	 * depends on a sibling being alive, so a kill -9 of any other daemon changes nothing here.
7	 *
8	 * It serves only the box's own access-point address, never every interface: --bind has no
9	 * default but loopback. Until the real source exists it answers from the synthetic one,
10	 * and says so on every log line (src=synth).
11	 */
12	#include "common/log.h"
13	#include "interface/route.h"
14	#include "interface/server.h"
15	#include "interface/synth_source.h"
16	
17	#include <arpa/inet.h>
18	#include <errno.h>
19	#include <signal.h>
20	#include <stdbool.h>
21	#include <stdio.h>
22	#include <stdlib.h>
23	#include <string.h>
24	#include <time.h>
25	
26	#define DEFAULT_BIND         "127.0.0.1"
27	#define DEFAULT_PORT         8080u
28	#define DEFAULT_HEARTBEAT_S  3600u
29	#define MAX_HEARTBEAT_S      86400u
30	
31	typedef struct {
32	    const char *bind;
33	    uint16_t    port;
34	    unsigned    heartbeat_s;
35	} args_t;
36	
37	typedef enum { ARGS_OK, ARGS_HELP, ARGS_USAGE } args_result_t;
38	
39	static volatile sig_atomic_t g_stop;
40	
41	static void on_signal(int sig)
42	{
43	    g_stop = sig;
44	}
45	
46	/* ------------------------------------------------------------------ arguments */
47	
48	static void usage(FILE *to)
49	{
50	    fprintf(to,
51	            "usage: statusd [--bind ADDR] [--port N] [--heartbeat-s N]\n"
52	            "  --bind ADDR       IPv4 address to serve on (default " DEFAULT_BIND ")\n"
53	            "  --port N          TCP port, 0 for any free one (default %u)\n"
54	            "  --heartbeat-s N   seconds between heartbeat log lines, 1 to %u (default %u)\n"
55	            "exit status: 0 stopped by SIGTERM or SIGINT, 1 could not run, 2 bad arguments\n",
56	            DEFAULT_PORT, MAX_HEARTBEAT_S, DEFAULT_HEARTBEAT_S);
57	}
58	
59	/* s is wholly decimal digits and at most max. */
60	static bool parse_number(const char *s, unsigned long max, unsigned long *out)
61	{
62	    char *end;
63	
64	    if (s[0] < '0' || s[0] > '9') return false;     /* no sign, no space, not empty */
65	    errno = 0;
66	    *out = strtoul(s, &end, 10);
67	    return errno == 0 && *end == '\0' && *out <= max;
68	}
69	
70	static args_result_t parse_args(int argc, char **argv, args_t *a)
71	{
72	    a->bind = DEFAULT_BIND;
73	    a->port = (uint16_t)DEFAULT_PORT;
74	    a->heartbeat_s = DEFAULT_HEARTBEAT_S;
75	
76	    for (int i = 1; i < argc; i++) {
77	        const char *flag = argv[i];
78	        unsigned long n;
79	
80	        if (strcmp(flag, "--help") == 0 || strcmp(flag, "-h") == 0) {
81	            usage(stdout);
82	            return ARGS_HELP;
83	        }
84	        if (i + 1 >= argc || (strcmp(flag, "--bind") != 0 && strcmp(flag, "--port") != 0 &&
85	                              strcmp(flag, "--heartbeat-s") != 0)) {
86	            fprintf(stderr, "statusd: %s: %s\n", flag,
87	                    i + 1 >= argc && strncmp(flag, "--", 2) == 0 ? "needs a value" : "unknown argument");
88	            usage(stderr);
89	            return ARGS_USAGE;
90	        }
91	        const char *value = argv[++i];
92	
93	        if (strcmp(flag, "--bind") == 0) {
94	            struct in_addr probe;
95	            if (inet_pton(AF_INET, value, &probe) != 1) {
96	                fprintf(stderr, "statusd: --bind: %s is not an IPv4 address\n", value);
97	                return ARGS_USAGE;
98	            }
99	            a->bind = value;
100	        } else if (strcmp(flag, "--port") == 0) {
101	            if (!parse_number(value, 65535, &n)) {
102	                fprintf(stderr, "statusd: --port: %s is not 0 to 65535\n", value);
103	                return ARGS_USAGE;
104	            }
105	            a->port = (uint16_t)n;
106	        } else {
107	            if (!parse_number(value, MAX_HEARTBEAT_S, &n) || n == 0) {
108	                fprintf(stderr, "statusd: --heartbeat-s: %s is not 1 to %u\n", value, MAX_HEARTBEAT_S);
109	                return ARGS_USAGE;
110	            }
111	            a->heartbeat_s = (unsigned)n;
112	        }
113	    }
114	    return ARGS_OK;
115	}
116	
117	/* ---------------------------------------------------------------------- clocks */
118	
119	static uint64_t wall_seconds(void)
120	{
121	    static uint64_t last;
122	    struct timespec ts;
123	
124	    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) LOG_E("clock_gettime: %s", strerror(errno));
125	    else last = (uint64_t)ts.tv_sec;
126	    return last;
127	}
128	
129	static uint64_t mono_ms(void)
130	{
131	    struct timespec ts;
132	
133	    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
134	        LOG_E("clock_gettime: %s", strerror(errno));
135	        return 0;
136	    }
137	    return (uint64_t)ts.tv_sec * 1000u + (uint64_t)ts.tv_nsec / 1000000u;
138	}
139	
140	/* ----------------------------------------------------------------- the source */
141	
142	/* The synthetic source, moved to the real time before each request, so that its samples
143	 * are from now and keep moving. The real source (a client of ctl.sock) replaces this whole
144	 * struct, and route.c never knows which it has. */
145	typedef struct {
146	    synth_t  synth;
147	    source_t inner;
148	    source_t outer;
149	} live_source_t;
150	
151	static ssize_t clocked_query(void *ctx, const char *request, char *out, size_t cap)
152	{
153	    live_source_t *l = ctx;
154	
155	    synth_set_time(&l->synth, wall_seconds());
156	    return source_query(&l->inner, request, out, cap);
157	}
158	
159	/* ---------------------------------------------------------------------- setup */
160	
161	static int install_signals(void)
162	{
163	    struct sigaction stop = { .sa_handler = on_signal };   /* no SA_RESTART: poll must return */
164	    struct sigaction ignore = { .sa_handler = SIG_IGN };
165	
166	    sigemptyset(&stop.sa_mask);
167	    sigemptyset(&ignore.sa_mask);
168	    if (sigaction(SIGTERM, &stop, NULL) < 0 || sigaction(SIGINT, &stop, NULL) < 0) {
169	        LOG_E("sigaction: %s", strerror(errno));
170	        return -1;
171	    }
172	    if (sigaction(SIGPIPE, &ignore, NULL) < 0) {
173	        LOG_E("sigaction SIGPIPE: %s", strerror(errno));
174	        return -1;
175	    }
176	    return 0;
177	}
178	
179	/* About 280 KB between them, so they live in static storage, not on the stack. */
180	static server_t      srv;
181	static route_ctx_t   rc;
182	static live_source_t live;
183	
184	int main(int argc, char **argv)
185	{
186	    args_t args;
187	    int status = 0;
188	
189	    switch (parse_args(argc, argv, &args)) {
190	    case ARGS_OK:    break;
191	    case ARGS_HELP:  return 0;
192	    case ARGS_USAGE: return 2;
193	    }
194	
195	    log_init("statusd", LOG_INFO);
196	    log_set_src(SRC_SYNTH);             /* every line says so, while the data is made up */
197	
198	    if (install_signals() < 0) return 1;
199	
200	    synth_init(&live.synth, wall_seconds());
201	    live.inner = synth_source(&live.synth);
202	    live.outer = (source_t){ .query = clocked_query, .ctx = &live };
203	    rc.src = &live.outer;
204	
205	    if (server_open(&srv, args.bind, args.port, route_handle, &rc) < 0) return 1;
206	
207	    uint64_t every_ms = (uint64_t)args.heartbeat_s * 1000u;
208	    uint64_t next_heartbeat = mono_ms() + every_ms;
209	
210	    log_heartbeat(server_served(&srv), server_drops(&srv));   /* alive, from the first second */
211	    while (!g_stop) {
212	        if (server_step(&srv, 1000) < 0) {
213	            LOG_E("the server failed; exiting");
214	            status = 1;
215	            break;
216	        }
217	        if (mono_ms() >= next_heartbeat) {
218	            log_heartbeat(server_served(&srv), server_drops(&srv));
219	            next_heartbeat = mono_ms() + every_ms;
220	        }
221	    }
222	
223	    if (g_stop) LOG_I("signal %d: stopping", (int)g_stop);
224	    server_close(&srv);
225	    return status;
226	}
