11	#define ROUTE_VALUE_MAX   24u    /* a query value, after decoding */
12	#define ROUTE_LINE_MAX    160u   /* the request line built from a URL */
13	
14	/* PLACEHOLDER. "/" serves this stub until the real status page exists. It is replaced by
15	 * page.c in the "add the status page" commit, step 7 of the statusd series on branch
