36	/* The query keys /api/series takes, in the order they go into the request line. */
37	static const char *const series_keys[] = { "pid", "from", "to" };
38	#define NSERIES_KEYS (sizeof series_keys / sizeof series_keys[0])
39	
40	/* --------------------------------------------------------------- responses */
41	
42	static void set_empty_500(server_response_t *r)
43	{
44	    r->status = HTTP_STATUS_INTERNAL_ERROR;
45	    r->ctype = "text/plain";
46	    r->body_len = 0;
47	}
48	
49	static void set_text(server_response_t *r, int status, const char *ctype, const char *text)
50	{
51	    size_t n = strlen(text);
52	
53	    if (n > r->cap) { set_empty_500(r); return; }
54	    memcpy(r->body, text, n);
55	    r->status = status;
56	    r->ctype = ctype;
57	    r->body_len = n;
