59	
60	/* {"ok":false,"code":"...","reason":"..."} */
61	static void set_error(server_response_t *r, int status, const char *code, const char *reason)
62	{
63	    json_t j;
64	
65	    json_init(&j, r->body, r->cap);
66	    json_begin_object(&j);
67	    json_key(&j, "ok");
68	    json_bool(&j, false);
69	    json_key(&j, "code");
70	    json_string(&j, code);
71	    json_key(&j, "reason");
72	    json_string(&j, reason);
73	    json_end_object(&j);
74	    ssize_t n = json_finish(&j);
75	    if (n < 0) { set_empty_500(r); return; }
76	    r->status = status;
77	    r->ctype = "application/json";
78	    r->body_len = (size_t)n;
79	}
80	
81	static int status_for_code(const char *code)
82	{
83	    if (strcmp(code, "usage") == 0) return HTTP_STATUS_BAD_REQUEST;
84	    if (strcmp(code, "unknown_pid") == 0 || strcmp(code, "unknown_verb") == 0)
85	        return HTTP_STATUS_NOT_FOUND;
86	    if (strcmp(code, "unavailable") == 0) return HTTP_STATUS_UNAVAILABLE;
87	    return HTTP_STATUS_INTERNAL_ERROR;
88	}
89	
90	/* The source's records as {"ok":true,"records":[{"tag":...,<fields>}]}. Returns false, with
91	 * the reason in *why, if the reply cannot be shown. */
92	static bool records_to_json(server_response_t *r, const char *reply, size_t n, const char **why)
93	{
94	    const char *cur = reply, *end = reply + n;
95	    kv_line_t rec;
96	    json_t j;
97	
98	    json_init(&j, r->body, r->cap);
99	    json_begin_object(&j);
100	    json_key(&j, "ok");
101	    json_bool(&j, true);
102	    json_key(&j, "records");
103	    json_begin_array(&j);
104	    while (kv_reply_next(&cur, end, &rec) == KV_RECORD) {
105	        if (kv_get(&rec, "tag") != NULL) {
106	            LOG_E("source record %s has a field called tag", rec.tag);
107	            *why = "source sent a field named tag";
108	            return false;
109	        }
110	        json_begin_object(&j);
111	        json_key(&j, "tag");
112	        json_string(&j, rec.tag);
113	        for (size_t i = 0; i < rec.nfields; i++) {
114	            json_key(&j, rec.f[i].key);
115	            switch (rec.f[i].type) {
116	            case KV_STR:  json_string(&j, rec.f[i].val); break;
117	            case KV_NUM:  json_number(&j, rec.f[i].val); break;
118	            case KV_NULL: json_null(&j); break;
119	            }
120	        }
121	        json_end_object(&j);
122	    }
123	    json_end_array(&j);
124	    json_end_object(&j);
125	
126	    ssize_t len = json_finish(&j);
127	    if (len < 0) {
128	        LOG_E("a reply of %zu bytes does not fit a %zu-byte response", n, r->cap);
129	        *why = "response did not fit";
130	        return false;
131	    }
132	    r->status = HTTP_STATUS_OK;
133	    r->ctype = "application/json";
134	    r->body_len = (size_t)len;
135	    return true;
136	}
137	
138	/* ------------------------------------------------------------ the request line */
139	
140	/* A query value is one token of a line sent to the source: nothing that could end a
141	 * string, start a field or a line, or surprise a parser. */
142	static bool safe_value(const char *v)
143	{
144	    size_t n = strlen(v);
145	
146	    if (n == 0 || n > ROUTE_VALUE_MAX) return false;
147	    for (size_t i = 0; i < n; i++) {
148	        char c = v[i];
149	        bool ok = (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') ||
150	                  strchr(":+.,_/-", c) != NULL;
151	        if (!ok) return false;
152	    }
153	    return true;
154	}
155	
156	/* Every key must be one of series_keys, at most once, and no pair may be empty. On success
157	 * sets bit i of *seen for each series_keys[i] present and returns NULL; else the reason. */
158	static const char *check_keys(const char *query, unsigned *seen)
159	{
160	    *seen = 0;
161	    for (const char *p = query; *p != '\0'; ) {
162	        size_t pair = strcspn(p, "&");
163	        size_t klen = strcspn(p, "=&");
164	        size_t k = 0;
165	
166	        while (k < NSERIES_KEYS && !(strlen(series_keys[k]) == klen &&
167	                                     memcmp(p, series_keys[k], klen) == 0)) k++;
168	        if (k == NSERIES_KEYS) return "unknown query key";
169	        if (*seen & (1u << k)) return "repeated query key";
170	        *seen |= 1u << k;
171	
172	        p += pair;
173	        if (*p == '&' && *++p == '\0') return "empty query pair";
174	    }
175	    return NULL;
176	}
177	
178	/* series pid="0C" from="-5m" to=1800000000. pid is always a string (PID 04 has a leading
179	 * zero, and is no number); from and to are bare when they are all digits, epoch seconds.
180	 * Returns NULL, or the reason the URL was refused. */
181	static const char *build_series(const char *query, char *line, size_t cap)
182	{
183	    unsigned seen;
184	    const char *why = check_keys(query, &seen);
185	    size_t len = (size_t)snprintf(line, cap, "series");
186	
187	    if (why != NULL) return why;
188	    for (size_t k = 0; k < NSERIES_KEYS; k++) {
189	        char v[HTTP_QUERY_MAX];
190	
191	        if (!(seen & (1u << k))) continue;
192	        if (http_query_get(query, series_keys[k], v, sizeof v) != 0) return "bad query value";
193	        if (!safe_value(v)) return "unsafe query value";
194	
195	        bool bare = k != 0 && strspn(v, "0123456789") == strlen(v);
