205	void route_handle(void *ctx, const http_request_t *req, server_response_t *resp)
206	{
207	    route_ctx_t *rc = ctx;
208	    char line[ROUTE_LINE_MAX];
209	    const char *why = NULL;
210	    size_t found = NAPI;
211	
212	    if (strcmp(req->path, "/") == 0) {
213	        if (req->query[0] != '\0') set_text(resp, HTTP_STATUS_BAD_REQUEST, "text/plain", "bad request\n");
214	        else set_text(resp, HTTP_STATUS_OK, "text/html; charset=utf-8", placeholder_page);
215	        return;
216	    }
217	    if (strncmp(req->path, "/api/", 5) != 0) {
218	        set_text(resp, HTTP_STATUS_NOT_FOUND, "text/plain", "not found\n");
219	        return;
220	    }
221	    for (size_t i = 0; i < NAPI; i++)
222	        if (strcmp(req->path, api[i].path) == 0) found = i;
223	    if (found == NAPI) {
224	        set_error(resp, HTTP_STATUS_NOT_FOUND, "not_found", "no such route");
225	        return;
226	    }
227	
228	    if (strcmp(api[found].verb, "series") == 0) {
229	        why = build_series(req->query, line, sizeof line);
230	    } else if (req->query[0] != '\0') {
231	        why = "this route takes no query";
232	    } else {
233	        snprintf(line, sizeof line, "%s", api[found].verb);
234	    }
235	    if (why != NULL) {
236	        set_error(resp, HTTP_STATUS_BAD_REQUEST, "usage", why);
237	        return;
238	    }
239	
240	    ssize_t n = source_query(rc->src, line, rc->reply, sizeof rc->reply);
241	    if (n < 0) {
242	        LOG_E("the source's reply to \"%s\" did not fit %u bytes", line, ROUTE_REPLY_MAX);
243	        set_error(resp, HTTP_STATUS_INTERNAL_ERROR, "internal", "reply did not fit");
244	        return;
245	    }
246	
247	    kv_line_t final;
248	    switch (kv_reply_check(rc->reply, (size_t)n, &final)) {
249	    case KV_OK:
250	        if (!records_to_json(resp, rc->reply, (size_t)n, &why))
251	            set_error(resp, HTTP_STATUS_INTERNAL_ERROR, "internal", why);
252	        return;
253	    case KV_ERR:
254	        set_error(resp, status_for_code(final.err_code), final.err_code, final.err_reason);
255	        return;
256	    case KV_RECORD:
257	    case KV_BAD:
258	    case KV_INCOMPLETE:
259	        break;
260	    }
261	    LOG_E("the source's reply to \"%s\" is malformed", line);
262	    set_error(resp, HTTP_STATUS_INTERNAL_ERROR, "internal", "malformed source reply");
263	}
