20	typedef struct {
21	    char  *buf;
22	    size_t cap, len;
23	    bool   over;   /* a line did not fit: the reply is not whole */
24	} out_t;
25	
26	static void outf(out_t *o, const char *fmt, ...) __attribute__((format(printf, 2, 3)));
27	
28	static void outf(out_t *o, const char *fmt, ...)
29	{
30	    if (o->over) return;
31	    size_t room = o->cap - o->len;
32	    va_list ap;
33	    va_start(ap, fmt);
34	    int n = vsnprintf(o->buf + o->len, room, fmt, ap);
35	    va_end(ap);
36	    if (n < 0 || (size_t)n >= room) { o->over = true; return; }
37	    o->len += (size_t)n;
38	}
39	
40	static void reply_err(out_t *o, const char *code, const char *reason)
41	{
42	    outf(o, "err %s %s\n", code, reason);
43	}
44	
45	/* A repeatable stand-in for noise: the same input gives the same bits on every machine. */
46	static uint32_t mix(uint64_t x)
47	{
48	    x ^= x >> 33;
49	    x *= 0xff51afd7ed558ccdULL;
50	    x ^= x >> 33;
51	    x *= 0xc4ceb9fe1a85ec53ULL;
52	    x ^= x >> 33;
53	    return (uint32_t)x;
54	}
55	
56	static double noise(uint64_t t, uint64_t k)   /* -1.0 to 1.0 */
57	{
58	    return (double)(mix(t * 31u + k) % 2001u) / 1000.0 - 1.0;
59	}
60	
61	static uint64_t ago(uint64_t now, uint64_t secs)
62	{
63	    return now >= secs ? now - secs : 0;
64	}
