66	static const kv_field_t *find(const kv_line_t *l, const char *key)
67	{
68	    for (size_t i = 0; i < l->nfields; i++)
69	        if (strcmp(l->f[i].key, key) == 0) return &l->f[i];
70	    return NULL;
71	}
