75	static const struct {
76	    const char *name;
77	    unsigned    pid, rss_kb, restarts, events_per_s;
78	} procs[] = {
79	    { "supervisor", 101, 1400, 0, 1 },  { "obdd",    102, 2100, 0, 15 },
80	    { "ambientd",   103, 1500, 0, 1 },  { "storaged", 104, 3200, 0, 16 },
81	    { "analyzed",   105, 4800, 2, 16 }, { "statusd",  106, 2600, 0, 1 },
82	};
83	#define NPROCS (sizeof procs / sizeof procs[0])
84	
85	static void reply_status(const synth_t *s, out_t *o)
86	{
87	    uint64_t up = s->now_s - s->t0 + BOOT_AGO_S;
88	
89	    for (size_t i = 0; i < NPROCS; i++) {
90	        /* analyzed restarted fifteen minutes ago, so its uptime is shorter. */
91	        uint64_t u = procs[i].restarts > 0 ? s->now_s - s->t0 + 900 : up;
92	        outf(o, "proc name=\"%s\" state=\"up\" pid=%u uptime_s=%llu restarts=%u rss_kb=%u "
93	                "cpu_pct=%.1f events=%llu drops=0 src=\"synth\"\n",
94	             procs[i].name, procs[i].pid, (ull)u, procs[i].restarts,
95	             procs[i].rss_kb + mix(s->now_s / 10 + i) % 64u,
96	             0.2 + (double)(mix(s->now_s / 5 + 7 * i) % 40u) / 10.0,
97	             (ull)(u * procs[i].events_per_s));
98	    }
99	    outf(o, "ring name=\"obd\" depth=%u capacity=4096 overruns=0 src=\"synth\"\n",
100	         mix(s->now_s + 1) % 40u);
101	    outf(o, "ring name=\"ambient\" depth=%u capacity=4096 overruns=0 src=\"synth\"\n",
102	         mix(s->now_s + 2) % 3u);
103	    outf(o, "link dongle=\"up\" probe=\"present\" light=\"green\" time_trusted=1 "
104	            "src=\"synth\"\n");
105	    outf(o, "srcmix live=0 replay=0 synth=%llu src=\"synth\"\n", (ull)(up * 16));
106	    outf(o, "ok\n");
107	}
