145	
146	static const struct {
147	    const char *pid;
148	    double      base, amp, period_s, wobble;
149	} signals[] = {
150	    { "0C", 1800, 700, 90, 25 },    /* engine speed, rpm */
151	    { "0D", 55, 25, 140, 1 },       /* vehicle speed, km/h */
152	    { "05", 88, 4, 600, 0.3 },      /* coolant, deg C */
153	    { "04", 35, 20, 90, 2 },        /* engine load, % */
154	    { "06", 0.5, 2, 60, 0.3 },      /* short-term fuel trim, % */
155	    { "07", 1.5, 0.5, 3000, 0.1 },  /* long-term fuel trim, % */
156	    { "probe", 21, 2, 1800, 0.1 },  /* cabin air, deg C */
157	};
158	#define NSIGNALS (sizeof signals / sizeof signals[0])
159	#define PROBE (NSIGNALS - 1)
160	
161	/* "now", "-<1 to 5 digits><s|m|h>", or Unix seconds as a bare number. */
162	static bool parse_when(const kv_line_t *req, const char *key, const char *dflt, uint64_t now,
163	                       uint64_t *out)
164	{
165	    const kv_field_t *f = find(req, key);
166	    const char *text = f != NULL ? f->val : dflt;
167	    kv_type_t type = f != NULL ? f->type : KV_STR;
168	
169	    if (type == KV_NULL) return false;
170	    if (type == KV_NUM) {
171	        size_t n = strlen(text);
172	        if (n > 12 || strspn(text, "0123456789") != n) return false;
173	        *out = strtoull(text, NULL, 10);
174	        return true;
175	    }
176	    if (strcmp(text, "now") == 0) { *out = now; return true; }
177	
178	    size_t d = text[0] == '-' ? strspn(text + 1, "0123456789") : 0;
179	    if (d < 1 || d > 5) return false;
180	    char unit = text[1 + d];
181	    if ((unit != 's' && unit != 'm' && unit != 'h') || text[2 + d] != '\0') return false;
182	    uint64_t secs = strtoull(text + 1, NULL, 10) * (unit == 's' ? 1u : unit == 'm' ? 60u : 3600u);
183	    if (secs > now) return false;
184	    *out = now - secs;
185	    return true;
186	}
187	
188	static void reply_series(const synth_t *s, const kv_line_t *req, out_t *o)
189	{
190	    const kv_field_t *pid = find(req, "pid");
191	    if (pid == NULL || pid->type != KV_STR) { reply_err(o, "usage", "series needs a pid"); return; }
192	
193	    size_t k = 0;
194	    while (k < NSIGNALS && strcmp(signals[k].pid, pid->val) != 0) k++;
195	    if (k == NSIGNALS) { reply_err(o, "unknown_pid", "no such pid"); return; }
196	
197	    uint64_t from, to;
198	    if (!parse_when(req, "from", "-5m", s->now_s, &from) ||
199	        !parse_when(req, "to", "now", s->now_s, &to)) {
200	        reply_err(o, "usage", "bad from or to");
201	        return;
202	    }
203	    if (from >= to || to - from > MAX_WINDOW_S) {
204	        reply_err(o, "usage", "window must be 1 to 3600 seconds");
205	        return;
206	    }
207	
208	    /* Samples sit on multiples of step, so two polls of one window agree on their times. */
209	    uint64_t step = (to - from) / MAX_SAMPLES + 1;
210	    for (uint64_t t = (from + step - 1) / step * step; t <= to; t += step) {
211	        if (k == PROBE && t % 900 < 60) {   /* the probe drops out for a minute */
212	            outf(o, "sample pid=\"%s\" t_s=%llu value=null src=\"synth\"\n", signals[k].pid,
213	                 (ull)t);
214	            continue;
215	        }
216	        double v = signals[k].base +
217	                   signals[k].amp * sin(2 * PI * (double)t / signals[k].period_s + (double)k) +
218	                   signals[k].wobble * noise(t, k);
219	        outf(o, "sample pid=\"%s\" t_s=%llu value=%.1f src=\"synth\"\n", signals[k].pid,
220	             (ull)t, v);
221	    }
222	    outf(o, "ok\n");
223	}
