1	/* statusd's routes without a socket: a URL goes in, a status and a body come out. A scripted
2	 * fake source shows what request line was built (and that hostile input never reaches it),
3	 * and the synthetic source shows the whole path end to end. */
4	#include "interface/route.h"
5	#include "interface/synth_source.h"
6	#include "common/log.h"
7	
8	#include <stdbool.h>
9	#include <stdio.h>
10	#include <stdlib.h>
11	#include <string.h>
12	
13	static int failures;
14	
15	#define CHECK(cond, msg) do { \
16	    if (!(cond)) { fprintf(stderr, "  FAIL %s:%d: %s\n", __FILE__, __LINE__, msg); \
17	                   failures++; } } while (0)
18	
19	#define NOW 1800000000ULL
20	
21	/* ---------------------------------------------------------------- fake source */
22	
23	typedef struct {
24	    const char *reply;    /* what the source answers with */
25	    ssize_t     force;    /* if not 0, returned instead of a reply */
26	    char        last[256];
27	    int         calls;
28	} fake_t;
29	
30	static fake_t fake;
31	
32	static ssize_t fake_query(void *ctx, const char *request, char *out, size_t cap)
33	{
34	    fake_t *f = ctx;
35	    size_t n = strlen(f->reply);
36	
37	    f->calls++;
38	    snprintf(f->last, sizeof f->last, "%s", request);
39	    if (f->force != 0) return f->force;
40	    if (n + 1 > cap) return -1;
41	    memcpy(out, f->reply, n + 1);
42	    return (ssize_t)n;
43	}
44	
45	static source_t fake_src = { fake_query, &fake };
46	static synth_t  syn;
47	static source_t synth_src;
48	static route_ctx_t rc;
49	
50	static void use_fake(const char *reply)
51	{
52	    memset(&fake, 0, sizeof fake);
53	    fake.reply = reply;
54	    rc.src = &fake_src;
55	}
56	
57	static void use_synth(void)
58	{
59	    synth_init(&syn, NOW);
60	    synth_src = synth_source(&syn);
61	    rc.src = &synth_src;
62	}
63	
64	/* ------------------------------------------------------------------- the call */
65	
66	#define CAP_MAX  SERVER_BODY_MAX
67	static char area[CAP_MAX + 16];
68	static char text[CAP_MAX + 1];
69	static server_response_t resp;
70	
71	/* Routes GET target with a response buffer of cap bytes; the body lands in text. */
72	static int call_cap(const char *target, size_t cap)
73	{
74	    char raw[600];
75	    http_request_t req;
76	
77	    snprintf(raw, sizeof raw, "GET %s HTTP/1.1\r\n\r\n", target);
78	    http_parse_t p = http_parse_request(raw, strlen(raw), &req);
79	    CHECK(p == HTTP_OK, target);   /* a test URL must get past the HTTP layer first */
80	    if (p != HTTP_OK) return -1;
81	
82	    memset(area, 0xAA, sizeof area);
83	    resp = (server_response_t){ HTTP_STATUS_INTERNAL_ERROR, "text/plain", area, cap, 0 };
84	    route_handle(&rc, &req, &resp);
85	
86	    for (size_t i = cap; i < sizeof area; i++)
87	        if ((unsigned char)area[i] != 0xAA) { CHECK(false, "wrote past the response buffer"); break; }
88	    CHECK(resp.body_len <= cap, "the length fits the buffer");
89	    if (resp.body_len > cap) resp.body_len = cap;
90	    memcpy(text, area, resp.body_len);
91	    text[resp.body_len] = '\0';
92	    return resp.status;
93	}
94	
95	static int call(const char *target) { return call_cap(target, CAP_MAX); }
96	
97	static bool starts(const char *s, const char *prefix) { return strncmp(s, prefix, strlen(prefix)) == 0; }
98	static bool has(const char *needle) { return strstr(text, needle) != NULL; }
99	
100	static size_t count(const char *hay, const char *needle)
101	{
102	    size_t n = 0;
103	    for (const char *p = hay; (p = strstr(p, needle)) != NULL; p += strlen(needle)) n++;
104	    return n;
105	}
106	
107	static bool json_error(const char *code)
108	{
109	    char want[96];
110	    snprintf(want, sizeof want, "{\"ok\":false,\"code\":\"%s\",\"reason\":\"", code);
111	    return starts(text, want);
112	}
113	
114	/* -------------------------------------------------------------------- tests */
115	
116	static void test_paths(void)
117	{
118	    use_fake("ok\n");
119	
120	    CHECK(call("/") == 200 && strcmp(resp.ctype, "text/html; charset=utf-8") == 0 &&
121	          has("<title>carwatch</title>"), "the status page");
122	    CHECK(call("/?x=1") == 400, "the page takes no query");
123	    CHECK(call("/nope") == 404 && strcmp(resp.ctype, "text/plain") == 0 &&
124	          strcmp(text, "not found\n") == 0, "an unknown path is a text 404");
125	    CHECK(call("/API/status") == 404 && strcmp(text, "not found\n") == 0, "paths are case-sensitive");
126	    CHECK(call("/api/nope") == 404 && json_error("not_found") &&
127	          strcmp(resp.ctype, "application/json") == 0, "an unknown /api/ path is a JSON 404");
128	    CHECK(call("/api/status/") == 404 && json_error("not_found"), "a trailing slash is another path");
129	    CHECK(call("/api/") == 404 && json_error("not_found"), "the bare prefix");
130	    CHECK(fake.calls == 0, "none of them reached the source");
131	}
132	
133	static void test_end_to_end(void)
134	{
135	    static const char *routes[] = { "/api/status", "/api/verdicts", "/api/faults",
136	                                    "/api/series?pid=0C", "/api/series?pid=probe&from=-1h" };
137	    static const char *verbs[] = { "status", "verdicts", "faults", "series pid=\"0C\"",
138	                                   "series pid=\"probe\" from=\"-1h\"" };
139	    static char reply[ROUTE_REPLY_MAX];
140	
141	    use_synth();
142	    synth_set_time(&syn, NOW);
143	    for (size_t i = 0; i < sizeof routes / sizeof routes[0]; i++) {
144	        CHECK(call(routes[i]) == 200, routes[i]);
145	        CHECK(strcmp(resp.ctype, "application/json") == 0, "JSON");
146	        CHECK(starts(text, "{\"ok\":true,\"records\":[") && strcmp(text + strlen(text) - 2, "]}") == 0,
147	              "the envelope");
148	        CHECK(count(text, "{") == count(text, "}") && count(text, "[") == count(text, "]"),
149	              "braces balance");
150	
151	        ssize_t n = source_query(&synth_src, verbs[i], reply, sizeof reply);
152	        size_t records = 0;
153	        for (const char *p = reply; (p = strchr(p, '\n')) != NULL; p++) records++;
154	        records--;   /* the terminator */
155	        CHECK(n > 0 && count(text, "{\"tag\":") == records, "one object per record");
156	        CHECK(count(text, "\"src\":\"synth\"") == records, "and every one says synth");
157	    }
158	
159	    call("/api/status");
160	    CHECK(has("\"tag\":\"proc\",\"name\":\"obdd\",\"state\":\"up\",\"pid\":102"),
161	          "strings quoted, numbers not");
162	    CHECK(has("\"restarts\":2") && has("\"time_trusted\":1"), "numbers");
163	    call("/api/verdicts");
164	    CHECK(has("\"end_s\":null") && has("\"sensors\":\"coolant,intake\""), "null, and a list string");
165	    call("/api/series?pid=0C");
166	    CHECK(has("\"pid\":\"0C\"") && has("\"t_s\":18") && !has("\"t_s\":\""), "a PID is a string, a time a number");
167	    call("/api/series?pid=probe&from=-1h");
168	    CHECK(has("\"value\":null") && has("\"value\":2"), "the probe drops out, then answers");
169	}
170	
171	static void test_conversion(void)
172	{
173	    use_fake("rec a=\"x\" n=1.5 z=null\nok\n");
174	    CHECK(call("/api/status") == 200, "ok");
175	    CHECK(strcmp(text, "{\"ok\":true,\"records\":[{\"tag\":\"rec\",\"a\":\"x\",\"n\":1.5,\"z\":null}]}") == 0,
176	          "each field keeps the type the source gave it");
177	
178	    use_fake("ok\n");
