342	/* A supervisor waits at most 60 s for a first sign of life (CLAUDE.md section 2.6), and the
343	 * default interval is an hour, so the first heartbeat must come at the start, not after it. */
344	static void test_heartbeat_at_start(void)
345	{
346	    proc_t p;
347	
348	    start_listening(&p, NULL);
349	    CHECK(wait_for(&p, "heartbeat rss_kib=", 2000), "a heartbeat within 2 s of starting");
350	    pump(&p, 500);
351	    CHECK(occurrences(p.log, "heartbeat rss_kib=") == 1, "and just the one until the interval is up");
352	    finish(&p);
353	}
354	
355	static void test_other_signals(void)
356	{
357	    proc_t p;
358	    uint16_t port = start_listening(&p, NULL);
359	
360	    kill(p.pid, SIGINT);
361	    CHECK(wait_exit(&p, 2000) == 0, "SIGINT is a clean exit too");
362	    CHECK(can_bind(port), "port free after SIGINT");
363	    finish(&p);
364	
365	    port = start_listening(&p, NULL);
366	    kill(p.pid, SIGKILL);
367	    CHECK(wait_exit(&p, 2000) == 128 + SIGKILL, "SIGKILL kills it");
368	    CHECK(can_bind(port), "and leaves nothing holding the port");
369	    finish(&p);
370	}
371	
372	int main(void)
373	{
374	    ssize_t n = readlink("/proc/self/exe", statusd_path, sizeof statusd_path - 16);
375	    char *slash;
376	
377	    if (n <= 0) { perror("readlink"); return 2; }
378	    statusd_path[n] = '\0';
379	    slash = strrchr(statusd_path, '/');
380	    if (slash == NULL) return 2;
381	    strcpy(slash + 1, "statusd");
382	
383	    signal(SIGPIPE, SIG_IGN);
384	    atexit(kill_all);
385	    alarm(90);                       /* the whole test, however it hangs */
386	
387	    test_usage_errors();
388	    test_port_taken_is_exit_1();
389	    test_lifecycle();
390	    test_heartbeat_at_start();
391	    test_other_signals();
392	    return failures == 0 ? 0 : 1;
393	}
