1	/* statusd as a process (CLAUDE.md section 2.6): started, queried over a real socket, sent
2	 * signals, and judged from outside by its exit codes, its log, its descriptors and the
3	 * port it leaves behind. The binary is the one next to this test, so `make asan` runs the
4	 * sanitized build. Every wait has a timeout, and a child is always killed on the way out. */
5	#include <arpa/inet.h>
6	#include <dirent.h>
7	#include <errno.h>
8	#include <fcntl.h>
9	#include <limits.h>
10	#include <netinet/in.h>
11	#include <poll.h>
12	#include <signal.h>
13	#include <stdbool.h>
14	#include <stdint.h>
15	#include <stdio.h>
16	#include <stdlib.h>
17	#include <string.h>
18	#include <sys/prctl.h>
19	#include <sys/socket.h>
20	#include <sys/wait.h>
21	#include <time.h>
22	#include <unistd.h>
23	
24	static int failures;
25	
26	#define CHECK(cond, msg) do { \
27	    if (!(cond)) { fprintf(stderr, "  FAIL %s:%d: %s\n", __FILE__, __LINE__, msg); \
28	                   failures++; } } while (0)
29	
30	/* ------------------------------------------------------------------ processes */
31	
32	typedef struct {
33	    pid_t  pid;           /* 0 once reaped */
34	    int    fd;            /* the child's stdout */
35	    char   log[16384];
36	    size_t len;
37	} proc_t;
38	
39	#define MAX_PROCS 4
40	static proc_t *started[MAX_PROCS];
41	static char statusd_path[PATH_MAX];
42	
43	static void kill_all(void)
44	{
45	    for (int i = 0; i < MAX_PROCS; i++) {
46	        if (started[i] != NULL && started[i]->pid > 0) {
47	            kill(started[i]->pid, SIGKILL);
48	            waitpid(started[i]->pid, NULL, 0);
49	            started[i]->pid = 0;
50	        }
51	    }
52	}
53	
54	static void sleep_ms(int ms)
55	{
56	    struct timespec ts = { ms / 1000, (long)(ms % 1000) * 1000000L };
57	    nanosleep(&ts, NULL);
58	}
59	
60	static uint64_t now_ms(void)
61	{
62	    struct timespec ts;
63	    clock_gettime(CLOCK_MONOTONIC, &ts);
64	    return (uint64_t)ts.tv_sec * 1000u + (uint64_t)ts.tv_nsec / 1000000u;
65	}
66	
67	/* Reads whatever the child has printed, waiting up to ms for something. Returns the
68	 * bytes read. After the child closes its stdout poll() answers at once for ever, so
69	 * callers that wait must not count on pump() to take time. */
70	static size_t pump(proc_t *p, int ms)
71	{
72	    struct pollfd pf = { .fd = p->fd, .events = POLLIN };
73	    size_t before = p->len;
74	
75	    if (p->fd < 0 || poll(&pf, 1, ms) <= 0) return 0;
76	    for (;;) {
77	        ssize_t r = read(p->fd, p->log + p->len, sizeof p->log - 1 - p->len);
78	        if (r <= 0) break;
79	        p->len += (size_t)r;
80	    }
81	    p->log[p->len] = '\0';
82	    return p->len - before;
83	}
84	
85	/* Waits on the real clock, not on a count of loops. */
86	static bool wait_for(proc_t *p, const char *needle, int ms)
87	{
88	    uint64_t end = now_ms() + (uint64_t)ms;
89	
90	    while (strstr(p->log, needle) == NULL && now_ms() < end)
91	        if (pump(p, 20) == 0) sleep_ms(5);
92	    return strstr(p->log, needle) != NULL;
93	}
94	
95	static size_t occurrences(const char *hay, const char *needle)
96	{
97	    size_t n = 0;
98	    for (const char *s = hay; (s = strstr(s, needle)) != NULL; s += strlen(needle)) n++;
99	    return n;
100	}
101	
102	/* Runs statusd with the given arguments (NULL-terminated). Stderr is dropped. */
103	static void start(proc_t *p, const char *const *args)
104	{
105	    char *argv[16] = { statusd_path };
106	    int fds[2];
107	    size_t n = 1;
108	
109	    for (size_t i = 0; args[i] != NULL && n < 14; i++) argv[n++] = (char *)args[i];
110	    argv[n] = NULL;
111	    memset(p, 0, sizeof *p);
112	    if (pipe2(fds, O_CLOEXEC) < 0) { perror("pipe2"); exit(2); }
113	
114	    p->pid = fork();
115	    if (p->pid < 0) { perror("fork"); exit(2); }
116	    if (p->pid == 0) {
117	        int null = open("/dev/null", O_WRONLY);
118	        prctl(PR_SET_PDEATHSIG, SIGKILL);              /* never outlive a test that crashes */
119	        dup2(fds[1], 1);
120	        if (null >= 0) dup2(null, 2);
121	        for (int fd = 3; fd < 256; fd++) close(fd);   /* nothing of the test's leaks in */
122	        execv(statusd_path, argv);
123	        _exit(127);
124	    }
125	    close(fds[1]);
126	    p->fd = fds[0];
127	    (void)fcntl(p->fd, F_SETFL, O_NONBLOCK);
128	    for (int i = 0; i < MAX_PROCS; i++)
129	        if (started[i] == NULL) { started[i] = p; break; }
130	}
131	
132	/* The exit code (128 + n for death by signal n), or -1 if it is still running after ms. */
133	static int wait_exit(proc_t *p, int ms)
134	{
135	    uint64_t end = now_ms() + (uint64_t)ms;
136	
137	    do {
138	        int st;
139	        pid_t r = waitpid(p->pid, &st, WNOHANG);
140	        if (r == p->pid) {
141	            p->pid = 0;
142	            pump(p, 0);
143	            return WIFEXITED(st) ? WEXITSTATUS(st) : 128 + WTERMSIG(st);
144	        }
145	        if (pump(p, 10) == 0) sleep_ms(5);
146	    } while (now_ms() < end);
147	    return -1;
148	}
149	
150	/* Ends a process and forgets it: p is usually on the caller's stack, and must not be
151	 * looked at again by kill_all() after the caller returns. */
152	static void finish(proc_t *p)
153	{
154	    if (p->pid > 0) { kill(p->pid, SIGKILL); waitpid(p->pid, NULL, 0); p->pid = 0; }
155	    if (p->fd >= 0) { close(p->fd); p->fd = -1; }
156	    for (int i = 0; i < MAX_PROCS; i++)
157	        if (started[i] == p) started[i] = NULL;
158	}
159	
160	/* Starts statusd on a free port and waits until it says it is listening. */
161	static uint16_t start_listening(proc_t *p, const char *const *extra)
162	{
163	    const char *args[10] = { "--bind", "127.0.0.1", "--port", "0" };
164	    size_t n = 4;
165	
166	    for (size_t i = 0; extra != NULL && extra[i] != NULL && n < 8; i++) args[n++] = extra[i];
167	    args[n] = NULL;
168	    start(p, args);
169	    if (!wait_for(p, "listening on 127.0.0.1:", 5000)) {
170	        CHECK(false, "statusd never said it was listening");
171	        return 0;
172	    }
173	    const char *at = strstr(p->log, "listening on 127.0.0.1:") + strlen("listening on 127.0.0.1:");
174	    return (uint16_t)atoi(at);
175	}
176	
177	/* ------------------------------------------------------------------- client */
178	
179	static size_t get(uint16_t port, const char *request, char *out, size_t cap)
180	{
181	    struct sockaddr_in a = { .sin_family = AF_INET, .sin_port = htons(port) };
182	    struct timeval tv = { 3, 0 };
183	    size_t len = 0;
184	    int fd = socket(AF_INET, SOCK_STREAM | SOCK_CLOEXEC, 0);
185	
186	    out[0] = '\0';
187	    if (fd < 0) return 0;
188	    inet_pton(AF_INET, "127.0.0.1", &a.sin_addr);
189	    setsockopt(fd, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof tv);
190	    setsockopt(fd, SOL_SOCKET, SO_SNDTIMEO, &tv, sizeof tv);
191	    if (connect(fd, (struct sockaddr *)&a, sizeof a) == 0 &&
192	        send(fd, request, strlen(request), MSG_NOSIGNAL) == (ssize_t)strlen(request)) {
193	        for (;;) {
194	            ssize_t r = recv(fd, out + len, cap - 1 - len, 0);
195	            if (r <= 0) break;
196	            len += (size_t)r;
197	        }
198	    }
199	    close(fd);
200	    out[len] = '\0';
201	    return len;
202	}
203	
204	static int status_of(const char *r) { return strncmp(r, "HTTP/1.1 ", 9) == 0 ? atoi(r + 9) : -1; }
205	
206	static char resp[65536];
207	
208	static int fetch(uint16_t port, const char *path)
209	{
210	    char req[256];
211	    snprintf(req, sizeof req, "GET %s HTTP/1.1\r\nHost: test\r\n\r\n", path);
212	    get(port, req, resp, sizeof resp);
213	    return status_of(resp);
214	}
