216	/* The newest "t_s" in the last response: the time of its latest sample. */
217	static unsigned long long latest_t_s(void)
218	{
219	    const char *last = NULL;
220	    for (const char *p = resp; (p = strstr(p, "\"t_s\":")) != NULL; p += 6) last = p + 6;
221	    return last != NULL ? strtoull(last, NULL, 10) : 0;
222	}
223	
224	static bool can_bind(uint16_t port)
225	{
226	    struct sockaddr_in a = { .sin_family = AF_INET, .sin_port = htons(port) };
227	    int one = 1;
228	    int fd = socket(AF_INET, SOCK_STREAM | SOCK_CLOEXEC, 0);
229	    bool ok;
230	
231	    inet_pton(AF_INET, "127.0.0.1", &a.sin_addr);
232	    setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, &one, sizeof one);
233	    ok = bind(fd, (struct sockaddr *)&a, sizeof a) == 0;
234	    close(fd);
235	    return ok;
236	}
