281	static void test_lifecycle(void)
282	{
283	    static const char *const fast[] = { "--heartbeat-s", "1", NULL };
284	    proc_t p;
285	    uint16_t port = start_listening(&p, fast);
286	
287	    CHECK(port != 0, "a port was chosen");
288	    const char *line = strstr(p.log, "listening on");
289	    const char *eol = line != NULL ? strchr(line, '\n') : NULL;
290	    CHECK(line != NULL && memmem(p.log, (size_t)(line - p.log), "src=synth", 9) != NULL,
291	          "the log line is labeled src=synth");
292	    CHECK(eol != NULL, "a whole line");
293	    CHECK(wait_for(&p, "heartbeat rss_kib=", 2000), "a heartbeat right at the start");
294	
295	    CHECK(fetch(port, "/api/status") == 200 && strstr(resp, "\"src\":\"synth\"") != NULL,
296	          "the API answers with synthetic records");
297	    CHECK(fetch(port, "/") == 200 && strstr(resp, "<title>carwatch</title>") != NULL, "and the page");
298	    get(port, "GARBAGE\r\n\r\n", resp, sizeof resp);
299	    CHECK(status_of(resp) == 400, "garbage is a 400");
300	    CHECK(fetch(port, "/api/faults") == 200, "and the server carries on");
301	
302	    /* The synthetic source is driven by the real clock, and the clock moves. */
303	    CHECK(fetch(port, "/api/series?pid=0C") == 200, "a series");
304	    unsigned long long t1 = latest_t_s(), now = (unsigned long long)time(NULL);
305	    CHECK(t1 + 310 >= now && t1 <= now + 2, "its latest sample is from now");
306	    pump(&p, 0);
307	    sleep_ms(2500);
308	    CHECK(fetch(port, "/api/series?pid=0C") == 200 && latest_t_s() > t1,
309	          "and a later request has later samples");
310	    pump(&p, 100);
311	    CHECK(occurrences(p.log, "heartbeat rss_kib=") >= 3, "a heartbeat every second asked for");
312	
313	    /* Descriptors: the listener, and nothing else beyond stdio, all close-on-exec. */
314	    char dir[64];
315	    snprintf(dir, sizeof dir, "/proc/%d/fd", (int)p.pid);
316	    DIR *d = opendir(dir);
317	    int open_fds = 0;
318	    struct dirent *e;
319	    while (d != NULL && (e = readdir(d)) != NULL) {
320	        int fd = atoi(e->d_name);
321	        if (e->d_name[0] == '.' || fd <= 2) continue;
322	        open_fds++;
323	        char info[64], buf[256];
324	        snprintf(info, sizeof info, "/proc/%d/fdinfo/%d", (int)p.pid, fd);
325	        FILE *f = fopen(info, "r");
326	        unsigned long flags = 0;
327	        while (f != NULL && fgets(buf, sizeof buf, f) != NULL)
328	            if (sscanf(buf, "flags: %lo", &flags) == 1) break;
329	        if (f != NULL) fclose(f);
330	        CHECK((flags & 02000000UL) != 0, "every descriptor is close-on-exec");
331	    }
332	    if (d != NULL) closedir(d);
333	    CHECK(d != NULL && open_fds == 1, "only the listening socket is open besides stdio");
334	
335	    kill(p.pid, SIGTERM);
336	    CHECK(wait_exit(&p, 2000) == 0, "SIGTERM is a clean exit, 0");
337	    CHECK(strstr(p.log, "stop served=") != NULL, "and it logs the stop");
338	    CHECK(can_bind(port), "and the port is free at once");
339	    finish(&p);
340	}
